  update catalogo_productos p set sinonimos=(select array_agg(distinct x) from unnest(p.sinonimos || n.sinonimos) x) from _nuevos n
    where lower(p.nombre)=lower(n.nombre) and p.activo and (p.sucursal_id=wp or p.sucursal_id is null);
  insert into catalogo_productos(nombre, sinonimos, categoria_id, unidad_default, sucursal_id, activo)
    select n.nombre, n.sinonimos, (select c.id from categorias_gasto c where c.nombre=n.categoria and (c.sucursal_id is null or c.sucursal_id=wp) limit 1), n.unidad, wp, true from _nuevos n
    where not exists (select 1 from catalogo_productos p where lower(p.nombre)=lower(n.nombre) and p.activo and (p.sucursal_id=wp or p.sucursal_id is null));
end $$;
